function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 50000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 5000)) return 'Each value is a whole number from 0 to 5000.';
  // The sorted, reversed-halves order succeeds whenever any valid order exists.
  const sorted = [...nums].sort((a, b) => a - b);
  const n = sorted.length;
  const out = [];
  for (let i = 0, small = Math.floor((n - 1) / 2), large = n - 1; i < n; i++) out.push(i % 2 === 0 ? sorted[small--] : sorted[large--]);
  for (let i = 1; i < n; i++) if (i % 2 === 1 ? out[i - 1] >= out[i] : out[i - 1] <= out[i]) return 'These values cannot be reordered to rise and fall in turn.';
  return null;
}

