function wiggleSort(nums) {
  const n = nums.length;
  let answer = null;
  if (n <= 10) {
    // Small arrays: depth-first search over the distinct values still unused.
    const counts = new Map();
    for (const v of nums) counts.set(v, (counts.get(v) || 0) + 1);
    const values = [...counts.keys()];
    const path = [];
    const search = () => {
      if (path.length === n) { answer = path.slice(); return true; }
      const k = path.length;
      for (const v of values) {
        if (counts.get(v) === 0) continue;
        if (k > 0 && (k % 2 === 1 ? !(path[k - 1] < v) : !(path[k - 1] > v))) continue;
        counts.set(v, counts.get(v) - 1);
        path.push(v);
        if (search()) return true;
        path.pop();
        counts.set(v, counts.get(v) + 1);
      }
      return false;
    };
    search();
  } else {
    // Larger arrays: count the values, deal the largest to the odd slots, then the rest to the even slots, high to low.
    const count = new Array(5001).fill(0);
    for (const v of nums) count[v]++;
    let value = 5000;
    answer = new Array(n);
    for (const start of [1, 0]) {
      for (let i = start; i < n; i += 2) {
        while (count[value] === 0) value--;
        answer[i] = value;
        count[value]--;
      }
    }
  }
  for (let i = 0; i < n; i++) nums[i] = answer[i];
}

