  };
  for (;;) {
    const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
    const top = size === 'large' ? (rand() < 0.5 ? 5000 : 400) : rand() < 0.6 ? 1 + Math.floor(rand() * 4) : 5000;
    // Keep the length and range; retry the values until a valid order exists.
